    border-style: dashed;
  }

  .submit-button {
    background-color: ButtonFace;
    color: ButtonText;
    border: 1px solid ButtonBorder;
  }

  .submit-button:focus {
    outline: 2px solid Highlight;
    outline-offset: -1px;
  }
}

